    public static int activeWorkers() { return workersForEffort(workerLimit(),current.performance()); }
    public static int workersForEffort(int limit,int effort) {
        if(limit<1 || effort<0 || effort>3)throw new IllegalArgumentException("Invalid worker effort");
        int percent=switch(effort){case 0 -> 30;case 1 -> 50;case 2 -> 80;default -> 100;};
        return Math.max(1,Math.min(limit,(int)Math.round(limit*(percent/100.0))));
    }
