    private static int loadWorkerLimit(Properties p) { int saved=Integer.parseInt(p.getProperty("workers",Integer.toString(DEFAULTS.workers()))); return saved==0?Runtime.getRuntime().availableProcessors():Math.max(1,Math.min(Runtime.getRuntime().availableProcessors(),saved)); }
    private static int loadPerformance(Properties p) {
        if(p.containsKey("generationEffort"))return Integer.parseInt(p.getProperty("generationEffort"));
        if(p.containsKey("performanceMode"))return Integer.parseInt(p.getProperty("performanceMode"))==1?3:1;
        return p.containsKey("performance")?(Integer.parseInt(p.getProperty("performance"))>=2?3:1):DEFAULTS.performance();
    }
    private static int loadPreviewMode(Properties p) {
        if(p.containsKey("previewMode")) return Integer.parseInt(p.getProperty("previewMode"));
        if(p.containsKey("genPreview")) return Boolean.parseBoolean(p.getProperty("genPreview"))?1:0;
        return DEFAULTS.previewMode();
    }
    private static MipmapMode loadMipmapMode(Properties properties) {
        try { return MipmapMode.valueOf(properties.getProperty("mipmapMode",DEFAULTS.mipmapMode().name())); }
        catch(IllegalArgumentException invalid) { return DEFAULTS.mipmapMode(); }
    }

